const $=id=>document.getElementById(id), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>(n>0?'+':'')+(n/10).toFixed(1), cls=n=>n>=0?'positive':'negative';
const tournaments=HQL.seed();let current='t1',page='events',timer,plan=null,entryId=null,filters={};
const pages={events:'赛事管理',roster:'选手管理',teamAdmin:'队伍管理',entry:'战果录入',settle:'阶段结算',rules:'计分规则',schedule:'总赛程',results:'总对局结果',teams:'队伍榜',players:'个人榜'};
const t=()=>tournaments.find(t=>t.id===current), scoped=()=>current==='all'?tournaments:[t()];
const options=(items,value)=>items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name)}</option>`).join('');
function toast(msg){$('toast').textContent=msg;$('toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('toast').hidden=true,4500)}
function safe(fn){try{fn()}catch(e){toast(e.message)}}
function header(title,sub,action=''){return `<div class="topline"><div><div class="eyebrow">HUAN QUE LOU / ${esc(pages[page])}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function empty(text){return `<div class="card empty">${text}</div>`}
function nav(){ $('navigation').innerHTML=Object.entries(pages).map(([id,name])=>`<button data-page="${id}" class="${id===page?'active':''}">${name}</button>`).join('');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;filters={};render();window.scrollTo(0,0)});$('scope').innerHTML=options([{id:'all',name:'全部赛事（仅列表汇总）'},...tournaments],current)}
$('scope').onchange=e=>{current=e.target.value;entryId=null;plan=null;filters={};render()};
function render(){nav();if(page==='events')renderEvents();else if(['schedule','results'].includes(page))renderQuery();else if(!t())$('content').innerHTML=header(pages[page],'请选择一个赛事；不同赛事不混合计分。')+empty('请在顶部选择单一赛事');else if(page==='roster')renderRoster();else if(page==='teamAdmin')renderTeamAdmin();else if(page==='entry')renderEntry();else if(page==='rules')renderRules();else if(page==='settle')renderSettlement();else renderBoard()}
function renderEvents(){
 $('content').innerHTML=header('每一项赛事，独立管理。','个人与团体赛各自拥有规则、赛程、成绩和阶段。','<button class="button" id="create">＋ 创建赛事</button>')+`<div class="tournament-grid">${scoped().map(x=>`<article class="card tournament-card"><span class="pill green">${x.type==='team'?'团体赛':'个人赛'}</span><h2>${esc(x.name)}</h2><p>${esc(x.rules.name)} · v${x.rules.version}</p><div class="stats"><div class="stat"><span>阶段</span><strong>${x.stages.length}</strong></div><div class="stat"><span>已发布</span><strong>${x.matches.filter(m=>m.status==='published').length}</strong></div><div class="stat"><span>报名</span><strong>${x.players.length}</strong></div></div><p class="subtle">${x.rules.ready?'基础计分可演示':'规则待核实，不能发布成绩'} · 独立赛事 ID ${x.id}</p><div class="actions"><button class="button" data-enter="${x.id}">管理此赛事</button><button class="button secondary" data-board="${x.id}">查看成绩</button></div></article>`).join('')}</div><div class="notice">原型展示逻辑隔离；正式版还需在服务端校验每个赛事的管理员权限，不能只靠页面筛选。</div><dialog id="create-dialog"><form id="create-form" class="card"><div class="card-head"><h2>创建独立赛事</h2><button type="button" class="button secondary" id="close-create">关闭</button></div><div class="form-stack"><label>赛事名称<input id="create-name" required maxlength="60" placeholder="例如：欢雀楼冬季个人赛"></label><label>比赛类型<select id="create-type"><option value="individual">个人赛</option><option value="team">团体赛</option></select></label><label>参考计分模板<select id="create-template">${options(Object.values(HQL.templates),'ml')}</select></label><p class="subtle">类型与计分模板分开选择。最高位战和联盟模板仍为参考草稿，需核实后另存自定义配置。新建赛事为空名单，请先录入队伍和选手，再安排出场。</p><label>首阶段名称<input id="create-stage" value="预赛" required maxlength="30"></label><label>下一阶段名称<input id="create-next" value="决赛" required maxlength="30"></label></div><div class="actions"><button class="button" type="submit">创建演示赛事</button></div></form></dialog>`;
 $('create').onclick=()=>$('create-dialog').showModal();$('close-create').onclick=()=>$('create-dialog').close();
 $('create-form').onsubmit=e=>{e.preventDefault();safe(()=>{const name=$('create-name').value.trim(),a=$('create-stage').value.trim(),b=$('create-next').value.trim();if(!name||!a||!b||a===b)throw Error('请填写赛事名称及两个不同的阶段名称');const x=HQL.makeEmptyTournament('t'+(tournaments.length+1),name,$('create-type').value,$('create-template').value);x.stages[0].name=a;x.stages[1].name=b;tournaments.push(x);current=x.id;filters={};render();toast('独立演示赛事已创建，已有比赛的成绩不会进入此赛事')})};
 document.querySelectorAll('[data-enter]').forEach(b=>b.onclick=()=>{current=b.dataset.enter;page='entry';entryId=null;render()});document.querySelectorAll('[data-board]').forEach(b=>b.onclick=()=>{current=b.dataset.board;page='players';filters={};render()});
}
function activeMatch(){return t()?.matches.find(m=>m.id===entryId)}
function renderEntry(){const x=t();const m=activeMatch();
 $('content').innerHTML=header('记录战果与精彩瞬间。',esc(x.name)+' · 罚分独立扣除，役满标记不重复加分。')+`<div class="filters"><label>选择对局<select id="match-select"><option value="">请选择已建对局</option>${options(x.matches.map(m=>({id:m.id,name:`${x.stages.find(s=>s.id===m.stageId).name} · ${m.table}桌 · 第${m.number}半庄 · ${m.status==='published'?'已发布':'草稿'}`})),entryId)}</select></label><label>新对局所属阶段<select id="new-stage">${options(x.stages.filter(s=>!s.locked))}</select></label><button class="button" id="new-match" ${x.stages.every(s=>s.locked)?'disabled':''}>＋ 新建半庄</button></div>`;
 $('match-select').onchange=e=>{entryId=e.target.value;renderEntry()};$('new-match').onclick=()=>safe(()=>{const m=HQL.newMatch(x,$('new-stage').value);entryId=m.id;renderEntry()});
 if(!m){$('content').insertAdjacentHTML('beforeend',empty('新建半庄或选择已有对局，录入成绩、罚分和役满。'));return}
 const locked=m.status==='published'||x.stages.find(s=>s.id===m.stageId).locked, disabled=locked?'disabled':'';
 $('content').insertAdjacentHTML('beforeend',`<div class="card"><div class="card-head"><h2>${esc(x.stages.find(s=>s.id===m.stageId).name)} · ${m.table}桌 · 第 ${m.number} 半庄</h2><span class="pill green">${locked?'已发布 · 只读':'演示草稿'} / 规则 v${m.rules.version}</span></div><div class="player-cards">${m.seats.map((s,i)=>{const p=x.players.find(p=>p.id===s.playerId);return `<div class="player-card"><span class="eyebrow">${['東','南','西','北'][i]} / 起家座次</span><h3>${esc(p.name)} <small class="subtle">${esc(x.teams.find(t=>t.id===s.teamId)?.name||'个人赛')}</small></h3><label>最终点数<input type="number" step="100" id="score-${i}" value="${s.score}" ${disabled}></label><div class="points num" id="net-${i}">—</div><div class="subtle" id="base-${i}">基础 / 罚分</div></div>`}).join('')}</div><div class="form-row" style="padding:0 22px"><label>剩余供托点数<input id="deposit" type="number" min="0" step="1000" value="${m.deposit}" ${disabled}></label><label>比赛日期<input id="entry-date" type="date" value="${m.date}" ${disabled}></label><label>桌号<input id="entry-table" maxlength="15" value="${esc(m.table)}" ${disabled}></label></div><p class="helper" style="margin-top:15px">${m.rules.kyotaku==='retained'?'本模板允许供托留存，四人点数＋剩余供托须等于起始总数。':'本模板要求先分配完终局供托，录入后剩余供托为 0。'}</p><div id="calc-status" class="notice" style="margin:20px" role="status"></div><div class="actions"><button class="button secondary" id="draft" ${disabled}>保存演示草稿</button><button class="button" id="publish" ${disabled}>校验并发布演示成绩</button></div></div><div class="event-layout"><div class="card"><div class="card-head"><h2>罚分事件</h2><span class="badge red">独立扣分</span></div><div class="event-list" id="penalty-list"></div>${locked?'':`<form id="penalty-form" class="form-stack"><div class="form-row"><label>选手<select id="penalty-player">${options(x.players)}</select></label><label>扣除积分（正数）<input id="penalty-amount" type="number" min="0.1" step="0.1" value="20" required></label></div><label>影响范围<select id="penalty-scope">${x.type==='team'?'<option value="both">个人并计入队伍（只扣一次）</option><option value="personal">仅个人榜</option><option value="team">仅所属队伍</option>':'<option value="personal">个人榜</option>'}</select></label><label>裁定原因<input id="penalty-reason" required maxlength="150" placeholder="例如：迟到，按赛事规则扣分"></label><button class="button secondary">添加罚分</button></form>`}</div><div class="card"><div class="card-head"><h2>役满记录</h2><span class="badge">成就标记</span></div><div class="event-list" id="yakuman-list"></div>${locked?'':`<form id="yakuman-form" class="form-stack"><div class="form-row"><label>选手<select id="yakuman-player">${options(x.players)}</select></label><label>局 / 本场<input id="yakuman-round" required maxlength="30" placeholder="南2局 0本场"></label></div><label>役种（可多选，复合记为同一次）<select id="yakuman-types" multiple required>${options(HQL.types.map(name=>({id:name,name})))}</select></label><div class="form-row"><label>役满倍数<input id="yakuman-multi" type="number" min="1" max="10" value="1" required></label><label>和牌方式<select id="yakuman-method"><option>自摸</option><option>荣和</option></select></label></div><button class="button secondary">添加役满标记</button></form>`}</div></div><p class="note">所有编辑暂存在当前页面。正式版需保存、审核和修订记录；本原型已发布结果只读。</p>`);
 m.seats.forEach((s,i)=>$('score-'+i).oninput=e=>{s.score=e.target.value===''?NaN:Number(e.target.value);x.revision++;calcEntry()});$('deposit').oninput=e=>{m.deposit=e.target.value===''?NaN:Number(e.target.value);x.revision++;calcEntry()};$('entry-date').onchange=e=>{m.date=e.target.value;x.revision++};$('entry-table').onchange=e=>{m.table=e.target.value;x.revision++};
 $('draft').onclick=()=>toast('演示草稿已保留在本页；尚未进入公开榜单');$('publish').onclick=()=>safe(()=>{if(!m.date||!m.table.trim())throw Error('请填写比赛日期和桌号');HQL.publish(x,m);renderEntry();toast('演示成绩已发布，相关榜单同步更新')});
 if(!locked){$('penalty-form').onsubmit=e=>{e.preventDefault();safe(()=>{const amount=Math.round(Number($('penalty-amount').value)*10),reason=$('penalty-reason').value.trim();if(amount<=0||!reason)throw Error('请填写扣分和原因');m.penalties.push({playerId:$('penalty-player').value,amount,scope:$('penalty-scope').value,reason});x.revision++;renderEntry();toast('罚分已加入草稿，发布后生效')})};$('yakuman-form').onsubmit=e=>{e.preventDefault();safe(()=>{const types=Array.from($('yakuman-types').selectedOptions).map(o=>o.value),round=$('yakuman-round').value.trim();if(!types.length||!round)throw Error('请选择役种并填写局信息');m.yakuman.push({playerId:$('yakuman-player').value,types,round,multiplier:Number($('yakuman-multi').value),method:$('yakuman-method').value});x.revision++;renderEntry();toast('役满已标记，不会额外改变积分')})}}
 $('penalty-list').innerHTML=m.penalties.map((p,i)=>`<div class="event"><div><strong>${esc(x.players.find(v=>v.id===p.playerId).name)} <span class="negative">${fmt(-p.amount)}</span></strong><div class="subtle">${esc(p.reason)} · ${{both:'个人及队伍',personal:'仅个人',team:'仅队伍'}[p.scope]}</div></div>${locked?'':`<button data-remove-penalty="${i}">移除此草稿事件</button>`}</div>`).join('')||'<p class="subtle">暂无罚分</p>';
 $('yakuman-list').innerHTML=m.yakuman.map((y,i)=>`<div class="event"><div><strong>${esc(x.players.find(p=>p.id===y.playerId).name)} · ${esc(y.types.join('＋'))}</strong><div class="subtle">${esc(y.round)} · ${esc(y.method)} · ${y.multiplier}倍役满 / 1次</div></div>${locked?'':`<button data-remove-yakuman="${i}">移除此草稿标记</button>`}</div>`).join('')||'<p class="subtle">暂无役满记录</p>';
 document.querySelectorAll('[data-remove-penalty]').forEach(b=>b.onclick=()=>{m.penalties.splice(Number(b.dataset.removePenalty),1);x.revision++;renderEntry()});document.querySelectorAll('[data-remove-yakuman]').forEach(b=>b.onclick=()=>{m.yakuman.splice(Number(b.dataset.removeYakuman),1);x.revision++;renderEntry()});calcEntry();
}
function calcEntry(){const m=activeMatch();try{const scores=HQL.scoreMatch(m,t());scores.forEach((s,i)=>{$('net-'+i).textContent=fmt(s.net);$('net-'+i).className='points num '+cls(s.net);$('base-'+i).textContent=`${s.tied?'并列 ':''}${s.rank}位 · 基础 ${fmt(s.base)} / 个人罚分 ${fmt(s.personalPenalty)}`});$('calc-status').className='notice';$('calc-status').textContent='✓ 点数与事件校验通过 · 个人净分合计 '+fmt(scores.reduce((n,s)=>n+s.net,0))+' pt';$('publish').disabled=m.status==='published'}catch(e){$('calc-status').className='notice error';$('calc-status').textContent=e.message;m.seats.forEach((s,i)=>$('net-'+i).textContent='—');$('publish').disabled=true}}
function filterBar(board=false){const x=t();return `<div class="filters"><label>阶段<select id="f-stage">${options([{id:'all',name:'全部阶段'},...(x?.stages||[])],filters.stage||'all')}</select></label>${board?`<label>分数口径<select id="f-metric"><option value="raw" ${filters.metric!=='competitive'?'selected':''}>原始累计（不含带入）</option><option value="competitive" ${filters.metric==='competitive'?'selected':''}>阶段竞技分（含带入）</option></select></label>`:`<label>起始日期<input id="f-from" type="date" value="${esc(filters.from||'')}"></label><label>结束日期<input id="f-to" type="date" value="${esc(filters.to||'')}"></label><label>状态<select id="f-status">${options([{id:'all',name:'全部状态'},...['published','draft'].map(id=>({id,name:id==='published'?'已发布':'草稿'}))],filters.status||'all')}</select></label><label>桌号<input id="f-table" placeholder="全部桌" value="${esc(filters.table||'')}"></label>`}<label>选手 / 队伍关键词<input id="f-keyword" placeholder="输入名称" value="${esc(filters.keyword||'')}"></label>${board?'':`<label class="check"><input type="checkbox" id="f-penalty" ${filters.penalty?'checked':''}>仅有罚分</label><label class="check"><input type="checkbox" id="f-yakuman" ${filters.yakuman?'checked':''}>仅有役满</label>`}<button class="button" id="apply-filter">筛选</button><button class="button secondary" id="clear-filter">重置</button></div>`}
function bindFilters(board=false){$('apply-filter').onclick=()=>{filters={stage:$('f-stage').value,keyword:$('f-keyword').value.trim(),...(board?{metric:$('f-metric').value}:{from:$('f-from').value,to:$('f-to').value,status:$('f-status').value,table:$('f-table').value.trim(),penalty:$('f-penalty').checked,yakuman:$('f-yakuman').checked})};if(filters.from&&filters.to&&filters.from>filters.to){toast('起始日期不能晚于结束日期');return}render()};$('clear-filter').onclick=()=>{filters={};render()}}
function matched(m,x){return (!filters.stage||filters.stage==='all'||m.stageId===filters.stage)&&(!filters.status||filters.status==='all'||m.status===filters.status)&&(!filters.from||m.date>=filters.from)&&(!filters.to||m.date<=filters.to)&&(!filters.table||m.table===filters.table)&&(!filters.penalty||m.penalties.length)&&(!filters.yakuman||m.yakuman.length)&&(!filters.keyword||m.seats.some(s=>{const p=x.players.find(p=>p.id===s.playerId);return p.name.includes(filters.keyword)||(x.teams.find(t=>t.id===s.teamId)?.name||'').includes(filters.keyword)}))}
function renderQuery(){const result=page==='results';const rows=scoped().flatMap(x=>x.matches.filter(m=>matched(m,x)).map(m=>({x,m}))).sort((a,b)=>b.m.date.localeCompare(a.m.date)||b.m.number-a.m.number);
 $('content').innerHTML=header(pages[page],current==='all'?'跨赛事列表汇总；成绩仍按各自规则计算。':esc(t().name)+' · 按条件定位对局。')+filterBar()+`<p class="note">${rows.length} 场符合条件 · 此处为管理视角，包含草稿；正式公众端仅显示已发布内容。</p><div class="card scroll-table"><table><thead><tr><th>日期 / 赛事</th><th>阶段 / 桌次</th><th>参赛选手</th><th>${result?'成绩与事件':'状态 / 事件'}</th></tr></thead><tbody>${rows.map(({x,m})=>{let scores;try{scores=HQL.scoreMatch(m,x)}catch{}return `<tr><td>${esc(m.date)}<small class="subtle">${esc(x.name)}</small></td><td>${esc(x.stages.find(s=>s.id===m.stageId).name)}<small class="subtle">${esc(m.table)}桌 · 第 ${m.number} 半庄</small></td><td>${m.seats.map(s=>esc(x.players.find(p=>p.id===s.playerId).name)).join(' / ')}${result?`<details><summary>查看四人成绩及事件</summary><div class="result-detail">${scores?scores.map((s,i)=>`<span>${esc(x.players.find(p=>p.id===s.playerId).name)}<br>${m.seats[i].score}点 · ${s.rank}位<br>基础 ${fmt(s.base)} / 罚分 ${fmt(s.personalPenalty)}<br><strong>个人 ${fmt(s.net)}</strong>${x.type==='team'?` / 队伍 ${fmt(s.teamNet)}`:''}</span>`).join(''):'规则待配置'}</div>${m.penalties.map(p=>`<p class="subtle">罚分：${esc(x.players.find(v=>v.id===p.playerId).name)} ${fmt(-p.amount)} · ${esc(p.reason)}</p>`).join('')}${m.yakuman.map(y=>`<p class="subtle">役满：${esc(x.players.find(p=>p.id===y.playerId).name)} · ${esc(y.types.join('＋'))} · ${esc(y.round)} · ${y.multiplier}倍</p>`).join('')}<p class="subtle">${esc(m.rules.name)} v${m.rules.version} · 剩余供托 ${m.deposit}</p></details>`:''}</td><td><span class="pill ${m.status==='published'?'green':''}">${m.status==='published'?'已发布':'草稿'}</span> ${m.penalties.length?'<span class="badge red">罚分 '+m.penalties.length+'</span>':''} ${m.yakuman.length?'<span class="badge">役满 '+m.yakuman.length+'</span>':''}</td></tr>`}).join('')}</tbody></table>${!rows.length?'<div class="empty">没有符合条件的对局，请调整或重置筛选。</div>':''}</div>`;bindFilters();
}
function renderBoard(){const x=t(),kind=page==='teams'?'team':'player';if(kind==='team'&&x.type==='individual'){$('content').innerHTML=header('队伍榜','当前赛事为个人赛。')+empty('个人赛不适用队伍榜，请查看个人榜。');return}let stage=filters.stage||'all',metric=filters.metric||'raw';const invalid=stage==='all'&&metric==='competitive';const rows=HQL.leaderboard(x,stage,kind,metric).filter(r=>!filters.keyword||r.name.includes(filters.keyword));
 $('content').innerHTML=header(pages[page],esc(x.name)+' · 原始成绩与阶段带入分开列示。')+filterBar(true)+(invalid?'<div class="notice error">竞技分属于特定阶段，请选择阶段。全部阶段只能查看原始累计。</div>':`<div class="notice">${metric==='competitive'?'当前阶段竞技分 = 本阶段基础分 + 罚分 + 上阶段带入':'原始累计只统计实际对局和处罚，不包含阶段带入。'}${kind==='player'&&x.type==='team'?' 团体赛的队伍折半不会自动改变个人表现。':''}</div><div class="card scroll-table"><table><thead><tr><th>排名</th><th>${kind==='team'?'队伍':'选手'}</th><th>场数</th><th>基础分</th><th>罚分</th><th>带入</th><th>役满次数</th><th>${metric==='competitive'?'竞技分':'原始净分'}</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="rank">${r.rank}</td><td><strong>${esc(r.name)}</strong></td><td>${r.games}</td><td>${fmt(r.base)}</td><td class="negative">${fmt(r.penalty)}</td><td>${fmt(r.carry)}</td><td>${r.yakuman}</td><td class="num ${cls(r.total)}">${fmt(r.total)}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">没有符合条件的参赛对象</div>':''}</div>`);bindFilters(true);
}
function renderRules(){const x=t(),r=x.rules;$('content').innerHTML=header('赛事规则，独立版本。',esc(x.name)+' · 只影响之后创建的对局。')+`<div class="card"><div class="card-head"><h2>${esc(r.name)}</h2><span class="pill green">v${r.version}</span></div><div class="rule-note">参考组织：${esc(HQL.templates[x.template].name)}。保存此页会生成明确标识的“自定义基础计分”版本，不能因此声称已完整复现组织全部规则。联盟条件顺位表尚待实现。</div><form id="rules-form"><div class="form-grid"><label>起始点<input id="r-start" type="number" step="100" min="100" value="${r.start}" required></label><label>返点<input id="r-return" type="number" step="100" min="100" value="${r.returnPoints}" required></label><div class="bonus-fields"><div class="full"><strong>最终顺位加分（含头名奖励）</strong><p class="subtle">ML 为 +50 / +10 / −10 / −30；已包含一位的 +20 奖励，不再重复添加。</p></div>${[0,1,2,3].map(i=>`<label>${i+1}位最终加分<input id="r-bonus-${i}" type="number" step="0.1" value="${r.bonuses?.[i]??''}" required></label>`).join('')}</div><label>终局供托<select id="r-deposit"><option value="distributed" ${r.kyotaku==='distributed'?'selected':''}>先分配完，再录最终点数</option><option value="retained" ${r.kyotaku==='retained'?'selected':''}>允许供托留存，单独记录</option></select></label><label>同点处理<select id="r-tie"><option value="split" ${r.tie==='split'?'selected':''}>平分顺位加分</option><option value="seat" ${r.tie==='seat'?'selected':''}>起家顺序优先</option></select></label><label class="full">修改说明<input id="r-reason" maxlength="150" required placeholder="说明本赛事采用的规则及修改原因"></label></div><div class="actions"><button class="button">保存为自定义新版本</button></div></form></div>`;
 $('rules-form').onsubmit=e=>{e.preventDefault();safe(()=>{const next={...r,id:'custom',name:'自定义基础计分',ready:true,start:Number($('r-start').value),returnPoints:Number($('r-return').value),bonuses:[0,1,2,3].map(i=>Number($('r-bonus-'+i).value)),kyotaku:$('r-deposit').value,tie:$('r-tie').value,version:r.version+1,reason:$('r-reason').value.trim()};if(!next.reason)throw Error('请填写修改说明');Scoring.calculate(Array(4).fill(next.start),next);x.rules=next;x.revision++;renderRules();toast('新规则已保存，已有对局仍使用各自快照')})};
}
function renderSettlement(){const x=t();if(plan&&plan.tournamentId!==x.id)plan=null;$('content').innerHTML=header('阶段结算，先预览再确认。',esc(x.name)+' · 原始战果不变，转换结果只生成下一阶段带入。','<button class="button secondary" id="add-stage">＋ 添加阶段</button>')+`<div class="stages">${x.stages.map(s=>`<div class="stage ${s.locked?'locked':''}">${esc(s.name)} · ${s.locked?'已结算锁定':'未结算'}</div>`).join('')}</div><div class="card"><div class="card-head"><h2>带入方案</h2><span class="pill">预览不影响榜单</span></div><div class="form-grid"><label>源阶段<select id="s-source">${options(x.stages.slice(0,-1).filter(s=>!s.locked),plan?.sourceStage)}</select></label><label>结算对象<select id="s-kind">${x.type==='team'?'<option value="team">队伍竞技分</option>':''}<option value="player">个人竞技分（独立方案）</option></select></label><label>变动逻辑<select id="s-preset"><option value="half">除以 2</option><option value="full">全额带入</option><option value="zero">清零</option><option value="custom">自定义比例</option></select></label><label>处罚处理<select id="s-penalties"><option value="scale">净分一起压缩</option><option value="full">基础分压缩，当前阶段罚分全额保留</option></select></label><label>比例分子<input id="s-num" type="number" value="1" min="0" step="1"></label><label>比例分母<input id="s-den" type="number" value="2" min="1" step="1"></label><label class="full">舍入到 0.1 分（明确负数方向）<select id="s-round"><option value="ceil">向正无穷：50.65→50.7，−50.65→−50.6</option><option value="floor">向负无穷：50.65→50.6，−50.65→−50.7</option><option value="trunc">向零截断：50.65→50.6，−50.65→−50.6</option><option value="halfAway">四舍五入，中点远离零：±50.65→±50.7</option></select></label></div><p class="helper">默认来源为当前阶段竞技分（包含历史带入）；团体赛默认只转换队伍，不自动折半个人表现榜。当前阶段所有未发布半庄会阻止结算。</p><div class="actions"><button class="button" id="preview">生成结算预览</button></div></div><div id="preview-content"></div><div class="card" style="margin-top:22px"><div class="card-head"><h2>已确认结算记录</h2></div><div class="event-list">${x.settlements.map(p=>`<div class="event"><div>${esc(x.stages.find(s=>s.id===p.sourceStage).name)} → ${esc(x.stages.find(s=>s.id===p.targetStage).name)}<p class="subtle">${p.kind==='team'?'队伍':'个人'} · ${p.options.numerator}/${p.options.denominator} · ${p.rows.filter(r=>r.advance).length} 个带入对象 · 来源修订 ${p.sourceRevision}</p><details><summary>查看结算快照</summary>${p.rows.map(r=>`<p class="subtle">${esc(r.name)}：${fmt(r.total)} → ${fmt(r.final)} ${r.advance?'晋级':'不晋级'} ${esc(r.reason)}</p>`).join('')}</details></div></div>`).join('')||'<p class="note">尚未确认任何阶段结算</p>'}</div></div><p class="note">原型先支持一次个人或队伍方案锁定源阶段；正式版可将多种结算对象纳入同一批次原子确认，详见设计记录。</p>`;
 const invalidate=()=>{plan=null;$('preview-content').innerHTML='<p class="note">方案已改变，请重新生成预览；旧人工覆盖已清除。</p>'};['s-source','s-kind','s-penalties','s-num','s-den','s-round'].forEach(id=>$(id).onchange=invalidate);$('s-preset').onchange=e=>{const map={half:[1,2],full:[1,1],zero:[0,1]};if(map[e.target.value]){[$('s-num').value,$('s-den').value]=map[e.target.value]}invalidate()};
 $('preview').onclick=()=>safe(()=>{const source=$('s-source').value,target=x.stages[x.stages.findIndex(s=>s.id===source)+1];plan=HQL.settlementPreview(x,source,target?.id,$('s-kind').value,{numerator:Number($('s-num').value),denominator:Number($('s-den').value),rounding:$('s-round').value,penalties:$('s-penalties').value});renderPreview()});
 $('add-stage').onclick=()=>{const name=prompt('新阶段名称（添加在末尾）');if(name?.trim())safe(()=>{if(x.stages.some(s=>s.name===name.trim()))throw Error('阶段名称不能重复');x.stages.push({id:'stage'+(x.stages.length+1),name:name.trim(),locked:false});x.revision++;plan=null;renderSettlement()})};if(plan){$('s-kind').value=plan.kind;$('s-num').value=plan.options.numerator;$('s-den').value=plan.options.denominator;$('s-penalties').value=plan.options.penalties;$('s-round').value=plan.options.rounding;renderPreview()}
}
function renderPreview(){if(!plan)return;const x=t();$('preview-content').innerHTML=`<div class="formula">${esc(x.stages.find(s=>s.id===plan.sourceStage).name)} → ${esc(x.stages.find(s=>s.id===plan.targetStage).name)} · 比例 ${plan.options.numerator}/${plan.options.denominator} · 可修改每行“最终带入”，修改须说明原因。</div><div class="card scroll-table"><table class="settlement-table"><thead><tr><th>晋级</th><th>对象</th><th>来源分</th><th>罚分</th><th>理论值</th><th>舍入后</th><th>最终带入</th><th>人工修改原因</th></tr></thead><tbody>${plan.rows.map((r,i)=>`<tr><td><input type="checkbox" data-advance="${i}" ${r.advance?'checked':''} aria-label="${esc(r.name)}晋级"></td><td>${esc(r.name)}</td><td>${fmt(r.total)}</td><td>${fmt(r.penalty)}</td><td>${(r.theoretical/10).toFixed(2)}</td><td>${fmt(r.suggested)}</td><td><input aria-label="${esc(r.name)}最终带入" type="number" step="0.1" value="${r.final/10}" data-final="${i}"></td><td><input class="reason" aria-label="${esc(r.name)}人工修改原因" placeholder="覆盖理论结果时必填" value="${esc(r.reason)}" data-reason="${i}"></td></tr>`).join('')}</tbody></table></div><div class="actions"><span class="preview-status" id="preview-status">来源版本 ${plan.sourceRevision} · 尚未生效</span><button class="button" id="commit-settlement">确认演示结算并锁定阶段</button></div>`;
 document.querySelectorAll('[data-advance]').forEach(e=>e.onchange=()=>plan.rows[Number(e.dataset.advance)].advance=e.checked);document.querySelectorAll('[data-final]').forEach(e=>e.oninput=()=>{const value=Number(e.value)*10;plan.rows[Number(e.dataset.final)].final=e.value===''||Math.abs(value-Math.round(value))>1e-6?NaN:Math.round(value)});document.querySelectorAll('[data-reason]').forEach(e=>e.oninput=()=>plan.rows[Number(e.dataset.reason)].reason=e.value);$('commit-settlement').onclick=()=>safe(()=>{HQL.commitSettlement(x,plan);plan=null;renderSettlement();toast('演示结算已确认；源阶段锁定，下一阶段带入已生成')});
}
render();
